const std = @import("std");
const math = std.math;
const mem = std.mem;
const Allocator = mem.Allocator;
const assert = std.debug.assert;

pub const Tensor = struct {
    data: []f32,
    shape: []const usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, shape: []const usize) !Tensor {
        var size: usize = 1;
        for (shape) |dim| {
            size *= dim;
        }
        const data = try allocator.alloc(f32, size);
        const shape_copy = try allocator.dupe(usize, shape);
        return Tensor{
            .data = data,
            .shape = shape_copy,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *Tensor) void {
        self.allocator.free(self.data);
        self.allocator.free(self.shape);
    }

    pub fn zero(self: *Tensor) void {
        @memset(self.data, 0);
    }

    pub fn random(self: *Tensor, seed: u64) void {
        var prng = std.rand.DefaultPrng.init(seed);
        const random_gen = prng.random();
        for (self.data) |*val| {
            val.* = random_gen.floatNorm(f32);
        }
    }

    pub fn dot(self: Tensor, other: Tensor, out: *Tensor) !void {
        assert(self.shape.len == 2);
        assert(other.shape.len == 2);
        assert(self.shape[1] == other.shape[0]);
        assert(out.shape[0] == self.shape[0]);
        assert(out.shape[1] == other.shape[1]);

        const M = self.shape[0];
        const K = self.shape[1];
        const N = other.shape[1];

        var i: usize = 0;
        while (i < M) : (i += 1) {
            var j: usize = 0;
            while (j < N) : (j += 1) {
                var sum: f32 = 0.0;
                var k: usize = 0;
                while (k < K) : (k += 1) {
                    sum += self.data[i * K + k] * other.data[k * N + j];
                }
                out.data[i * N + j] = sum;
            }
        }
    }

    pub fn add(self: Tensor, other: Tensor, out: *Tensor) void {
        assert(self.data.len == other.data.len);
        assert(self.data.len == out.data.len);

        const len = self.data.len;
        const vec_len = std.simd.suggestVectorLength(f32) orelse 1;
        var i: usize = 0;

        while (i + vec_len <= len) : (i += vec_len) {
            const v1: @Vector(vec_len, f32) = self.data[i..][0..vec_len].*;
            const v2: @Vector(vec_len, f32) = other.data[i..][0..vec_len].*;
            out.data[i..][0..vec_len].* = v1 + v2;
        }
        while (i < len) : (i += 1) {
            out.data[i] = self.data[i] + other.data[i];
        }
    }

    pub fn sigmoid(self: Tensor, out: *Tensor) void {
        for (self.data, 0..) |val, i| {
            out.data[i] = 1.0 / (1.0 + math.exp(-val));
        }
    }
};

pub const HebbianConfig = struct {
    learning_rate: f32 = 0.01,
    decay_rate: f32 = 0.001,
    plasticity_threshold: f32 = 0.1,
};

pub const AssociativeMemoryLayer = struct {
    weights: Tensor,
    trace: Tensor,
    config: HebbianConfig,
    allocator: Allocator,
    input_size: usize,
    output_size: usize,

    pub fn init(allocator: Allocator, input_size: usize, output_size: usize, config: HebbianConfig) !AssociativeMemoryLayer {
        var weights = try Tensor.init(allocator, &[_]usize{input_size, output_size});
        weights.random(0); 
        var trace = try Tensor.init(allocator, &[_]usize{input_size, output_size});
        trace.zero();

        return AssociativeMemoryLayer{
            .weights = weights,
            .trace = trace,
            .config = config,
            .allocator = allocator,
            .input_size = input_size,
            .output_size = output_size,
        };
    }

    pub fn deinit(self: *AssociativeMemoryLayer) void {
        self.weights.deinit();
        self.trace.deinit();
    }

    pub fn forward(self: *AssociativeMemoryLayer, input: Tensor, output: *Tensor) !void {
        try input.dot(self.weights, output);
        try self.updateTrace(input, output.*);
    }

    fn updateTrace(self: *AssociativeMemoryLayer, input: Tensor, output: Tensor) !void {
        const M = self.input_size;
        const N = self.output_size;

        var i: usize = 0;
        while (i < M) : (i += 1) {
            var j: usize = 0;
            while (j < N) : (j += 1) {
                const pre = input.data[i];
                const post = output.data[j];
                const coactivation = pre * post;

                const current_trace = self.trace.data[i * N + j];
                const new_trace = (1.0 - self.config.decay_rate) * current_trace + self.config.learning_rate * coactivation;
                self.trace.data[i * N + j] = new_trace;

                if (math.fabs(new_trace) > self.config.plasticity_threshold) {
                    self.weights.data[i * N + j] += new_trace * 0.1;
                }
            }
        }
    }
};

pub const FractalMemoryUnit = struct {
    layers: []AssociativeMemoryLayer,
    allocator: Allocator,
    depth: usize,

    pub fn init(allocator: Allocator, input_dim: usize, depth: usize) !FractalMemoryUnit {
        const layers = try allocator.alloc(AssociativeMemoryLayer, depth);
        var current_dim = input_dim;

        for (0..depth) |i| {
            const next_dim = if (i == depth - 1) input_dim else current_dim / 2;
            layers[i] = try AssociativeMemoryLayer.init(allocator, current_dim, next_dim, .{});
            current_dim = next_dim;
        }

        return FractalMemoryUnit{
            .layers = layers,
            .allocator = allocator,
            .depth = depth,
        };
    }

    pub fn deinit(self: *FractalMemoryUnit) void {
        for (self.layers) |*layer| {
            layer.deinit();
        }
        self.allocator.free(self.layers);
    }

    pub fn forward(self: *FractalMemoryUnit, input: Tensor, output: *Tensor) !void {
        var current_input = try Tensor.init(self.allocator, input.shape);
        @memcpy(current_input.data, input.data);

        var temp_output: Tensor = undefined;

        for (self.layers, 0..) |*layer, i| {
            const out_shape = &[_]usize{current_input.shape[0], layer.output_size};
            temp_output = try Tensor.init(self.allocator, out_shape);

            try layer.forward(current_input, &temp_output);

            if (i < self.depth - 1) {
                var activated_output = try Tensor.init(self.allocator, out_shape);
                temp_output.sigmoid(&activated_output);
                current_input.deinit();
                current_input = activated_output;
                temp_output.deinit();
            } else {
                @memcpy(output.data, temp_output.data);
                temp_output.deinit();
                current_input.deinit();
            }
        }
    }
};
