const std = @import("std");
const Tensor = @import("nested_hebbian_memory.zig").Tensor;

pub const NestedOptimizer = struct {
    learning_rate: f32,
    momentum: f32,
    velocity: std.ArrayList(Tensor),
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, model_params: []Tensor, lr: f32, momentum: f32) !NestedOptimizer {
        var velocity = std.ArrayList(Tensor).init(allocator);
        for (model_params) |param| {
            var v = try Tensor.init(allocator, param.shape);
            v.zero();
            try velocity.append(v);
        }
        return NestedOptimizer{
            .learning_rate = lr,
            .momentum = momentum,
            .velocity = velocity,
            .allocator = allocator,
        };
    }

    pub fn step(self: *NestedOptimizer, params: []Tensor, grads: []Tensor) void {
        std.debug.assert(params.len == grads.len);
        std.debug.assert(params.len == self.velocity.items.len);

        for (params, 0..) |*param, i| {
            const grad = grads[i];
            var vel = &self.velocity.items[i];

            for (vel.data, 0..) |*v, j| {
                const g = grad.data[j];
                v.* = self.momentum * v.* - self.learning_rate * g;
                param.data[j] += v.*;
            }
        }
    }

    pub fn deinit(self: *NestedOptimizer) void {
        for (self.velocity.items) |*v| {
            v.deinit();
        }
        self.velocity.deinit();
    }
};

pub const HebbianRegularizer = struct {
    strength: f32,

    pub fn apply(self: HebbianRegularizer, weights: *Tensor, activations: Tensor) void {
        const len = weights.data.len;
        const act_len = activations.data.len;

        var i: usize = 0;
        while (i < len) : (i += 1) {
            const act_idx = i % act_len; 
            const penalty = self.strength * (weights.data[i] * activations.data[act_idx]);
            weights.data[i] -= penalty;
        }
    }
};
