const std = @import("std");
const nhm = @import("nested_hebbian_memory.zig");
const opt = @import("fractal_optimizer.zig");

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const input_dim: usize = 256;
    const depth: usize = 4;

    var memory_unit = try nhm.FractalMemoryUnit.init(allocator, input_dim, depth);
    defer memory_unit.deinit();

    const batch_size: usize = 1;
    var input = try nhm.Tensor.init(allocator, &[_]usize{batch_size, input_dim});
    defer input.deinit();
    input.random(42);

    var output = try nhm.Tensor.init(allocator, &[_]usize{batch_size, input_dim});
    defer output.deinit();

    const epochs = 10;
    std.debug.print("Starting associative learning cycle...\n", .{});

    for (0..epochs) |epoch| {
        try memory_unit.forward(input, &output);

        var mse: f32 = 0.0;
        for (input.data, 0..) |val, i| {
            const diff = val - output.data[i];
            mse += diff * diff;
        }
        mse /= @as(f32, @floatFromInt(input_dim));

        std.debug.print("Epoch {d}: Reconstruction Error = {d:.6}\n", .{epoch, mse});

        // In a real scenario, we would update based on error here
        // The Hebbian update happens internally in forward() via updateTrace
    }

    std.debug.print("Associative binding complete.\n", .{});
}
